use std::io::{self, Write};
use unisphere_sdk::*;
use unisphere_output_otlp::OtlpJsonlWriter;
struct Loader { foreign: bool }
impl SnapshotLoader for Loader { fn read_snapshot(&self, source:&SnapshotRef,_:SnapshotLimits)->Result<NativeSnapshot,PipelineError>{let mut source=source.clone(); if self.foreign { source.path="/different/source.json".into(); } Ok(NativeSnapshot{source,revision:"synthetic-revision".into(),records:vec![]})} }
struct Mapper;
impl SnapshotAdapter for Mapper {fn name(&self)->&'static str{"fixture-snapshot"} fn map_snapshot(&self,_:&NativeSnapshot,_:MappingOptions)->Result<MappedSnapshot,PipelineError>{Ok(MappedSnapshot::default())}}
struct Fails;
impl Write for Fails {fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::other("private-io-text"))} fn flush(&mut self)->io::Result<()>{Ok(())}}
fn main(){let request=SnapshotRequest{source:SnapshotRef{path:"/explicit/source.json".into(),format:SnapshotFormat::JsonDocument,session_id:None},limits:SnapshotLimits::default(),options:MappingOptions::default()};
let collector=SnapshotCollector::new(Loader{foreign:false},Mapper,OtlpJsonlWriter);let mut bytes=Vec::new();let result=collector.collect_snapshot(&request,&mut bytes).unwrap();assert_eq!(result.records_written,1);assert_eq!(result.checkpoint.revision,"synthetic-revision");let doc:serde_json::Value=serde_json::from_slice(&bytes).unwrap();let attrs=doc["resourceLogs"][0]["scopeLogs"][0]["logRecords"][0]["attributes"].as_array().unwrap();assert!(!attrs.iter().any(|a|a["key"]=="unisphere.source.offset"));assert!(attrs.iter().any(|a|a["key"]=="unisphere.snapshot.records" && a["value"]["intValue"]=="0"));assert_eq!(collector.collect_snapshot(&request,&mut Fails).unwrap_err().kind(),PipelineErrorKind::Write);
let foreign=SnapshotCollector::new(Loader{foreign:true},Mapper,OtlpJsonlWriter);let mut untouched=Vec::new();assert_eq!(foreign.collect_snapshot(&request,&mut untouched).unwrap_err().kind(),PipelineErrorKind::InvalidData);assert!(untouched.is_empty());let context=unisphere_cli::CliContext{cwd:"/explicit".into(),stdout_is_terminal:false,version:"smoke".into()};let args=["unisphere","sessions","export","--adapter","fixture-snapshot","--input","source.json","--source-format","json-document"].map(Into::into).to_vec();let mut cli_out=Vec::new();let mut cli_err=Vec::new();assert_eq!(unisphere_cli::run_snapshot_sessions(args,&context,&collector,SnapshotFormat::JsonDocument,&mut cli_out,&mut cli_err),0);assert_eq!(cli_out,bytes);let summary:serde_json::Value=serde_json::from_slice(&cli_err).unwrap();assert_eq!(summary["data"]["revision"],"synthetic-revision");assert!(summary["data"].get("offset").is_none());println!("Actual injected snapshot CLI and SDK produce identical OTLP; summary is revision-based, not a fake byte cursor.");}
